package com.oms.order.service;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

/** Real MySQL transactions and shipment generation, using the isolated order test database. */
class OrderCarrierServiceTest extends OrderShipmentServiceTest {
    OrderCarrierService carrier;OrderCatalog catalog;
    @Override @BeforeEach void seed(){super.seed();carrier=new OrderCarrierService(repository);catalog=mock(OrderCatalog.class);ReflectionTestUtils.setField(carrier,"catalog",catalog);when(catalog.warehouses("VERIFY")).thenReturn(Arrays.asList(row("owner_code","O1","real_store_code","R1","wms_simulation_code","V1","connection_id",1,"provider","QIMEN"),row("owner_code","O1","real_store_code","R2","wms_simulation_code","V2","connection_id",1,"provider","QIMEN")));ReflectionTestUtils.setField(service,"catalog",catalog);when(catalog.validateShop("VERIFY",1)).thenReturn(row("channel_id",1));db.update("UPDATE oms_platform_order SET processing_payload=?",encode(row("trade_fullinfo_get_response",row("trade",row("receiver_state","北京市")))));}
    @AfterEach void clear(){for(String table:Arrays.asList("oms_order_shipment_log","oms_order_carrier_config","oms_order_carrier"))db.update("DELETE FROM "+table);}
    Map<String,Object> service(String store,String...excluded){return row("owner_code","O1","real_store_code",store,"warehouse_carrier_code","WMS_A", "provinces",Collections.emptyList(),"excluded_provinces",Arrays.asList(excluded));}
    void master(String code,List<Map<String,Object>> services,long revision,long enabled){long id=CarrierTestFixtures.standard(repository,code,revision,enabled);for(Map<String,Object> service:services)CarrierTestFixtures.outbound(repository,id,text(service,"real_store_code"),1,text(service,"warehouse_carrier_code"),(List<String>)service.get("excluded_provinces"));}
    void configure(long revision,long enabled,List<Map<String,Object>> routes,String...codes){carrier.saveConfiguration("VERIFY",row("channel_id",1,"revision",revision,"policy",row("enabled",enabled,"carrier_order",Arrays.asList(codes),"routes",routes)),"tester");}
    long shipment(){mirror(Arrays.asList(receipt(1,6,"V1","R1")));return number(generate(0).get(0),"id");}
    Map<String,Object> document(long id){return db.query("SELECT * FROM oms_order_shipment WHERE id=?",ROW,id).get(0);}
    Map<String,Object> match(long id,long version,String mode,String code){return carrier.match("VERIFY",row("mode",mode,"items",Arrays.asList(row("id",id,"control_version",version)),"standard_id",code.isEmpty()?0:db.queryForObject("SELECT id FROM oms_carrier_standard WHERE company_code='VERIFY' AND standard_code=?",Long.class,code),"reason","customer requested"),"operator").get(0);}
    @Test void newMultiWarehouseDocumentsMatchIndependentlyWithoutChangingQuantities(){master("A",Arrays.asList(service("R1"),service("R2","北京")),0,1);master("B",Arrays.asList(service("R2")),0,1);configure(0,1,Collections.emptyList(),"A","B");mirror(Arrays.asList(receipt(1,3,"V1","R1"),receipt(2,3,"V2","R2")));List<Map<String,Object>> created=generate(0);assertEquals(2,created.size());assertEquals("A",document(number(created.get(0),"id")).get("carrier_code"));assertEquals("B",document(number(created.get(1),"id")).get("carrier_code"));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment WHERE status='WAIT_DISPATCH'",Integer.class));assertEquals(6,db.queryForObject("SELECT SUM(quantity) FROM oms_order_shipment_line",Integer.class));assertEquals(10,db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));assertEquals(0,number(summary(),"shipped_quantity"));assertTrue(generate(1).isEmpty());}
    @Test void uncoveredRegionFailsWithReasonAndRetryUsesUpdatedCarrierScope(){master("A",Arrays.asList(service("R1","北京")),0,1);configure(0,1,Collections.emptyList(),"A");long s=shipment();Map<String,Object> failed=document(s);assertEquals("WAIT_CARRIER",failed.get("status"));assertEquals("FAILED",failed.get("carrier_match_status"));assertTrue(text(failed,"carrier_match_reason").contains("不支持当前收货省份"));master("A",Arrays.asList(service("R1")),1,1);assertEquals(true,match(s,1,"AUTO","").get("success"));assertEquals("WAIT_DISPATCH",document(s).get("status"));assertEquals(2,number(document(s),"control_version"));assertEquals(6,db.queryForObject("SELECT SUM(quantity) FROM oms_order_shipment_line",Integer.class));}
    @Test void manualAdjustmentRequiresShopWarehouseCoverageAndRecordsActorReason(){master("A",Arrays.asList(service("R1")),0,1);master("B",Arrays.asList(service("R1")),0,1);master("C",Arrays.asList(service("R1")),0,1);configure(0,1,Collections.emptyList(),"A","B");long s=shipment();assertEquals(false,match(s,1,"MANUAL","C").get("success"));assertEquals("A",document(s).get("carrier_code"));assertEquals(true,match(s,1,"MANUAL","B").get("success"));Map<String,Object> selected=document(s);assertEquals("B",selected.get("carrier_code"));assertEquals("MANUAL",selected.get("carrier_match_mode"));assertEquals("operator",selected.get("carrier_matched_by"));assertEquals("customer requested",selected.get("carrier_match_reason"));assertEquals(true,match(s,2,"AUTO","").get("success"));assertEquals("B",document(s).get("carrier_code"));assertEquals(2,number(document(s),"control_version"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_log WHERE action='CARRIER_ADJUST'",Integer.class));}
    @Test void disabledCarrierCannotBeChosenAndExistingSnapshotIsPreserved(){master("A",Arrays.asList(service("R1")),0,1);configure(0,1,Collections.emptyList(),"A");long s=shipment();String snapshot=text(document(s),"carrier_snapshot");master("A",Arrays.asList(service("R1")),1,0);assertEquals(false,match(s,1,"MANUAL","A").get("success"));assertEquals(snapshot,text(document(s),"carrier_snapshot"));assertEquals(false,((List<Map<String,Object>>)carrier.options("VERIFY",s).get("carriers")).get(0).get("available"));}
    @Test void missingProvinceAndMissingRulesCannotPretendToMatch(){db.update("UPDATE oms_platform_order SET processing_payload='{}'");master("A",Arrays.asList(service("R1")),0,1);configure(0,1,Collections.emptyList(),"A");long s=shipment();assertTrue(text(document(s),"carrier_match_reason").contains("省份缺失"));assertEquals(false,match(s,1,"MANUAL","A").get("success"));}
    @Test void autoDisabledStillAllowsExplicitManualSelection(){master("A",Arrays.asList(service("R1")),0,1);configure(0,0,Collections.emptyList(),"A");long s=shipment();assertEquals("WAIT_CARRIER",document(s).get("status"));assertEquals(true,match(s,1,"MANUAL","A").get("success"));}
    @Test void tenantStaleVersionPlatformHoldsAndWarehouseProcessingBlockWrites(){master("A",Arrays.asList(service("R1")),0,1);configure(0,1,Collections.emptyList(),"A");long s=shipment();assertEquals(false,match(s,0,"MANUAL","A").get("success"));assertThrows(IllegalArgumentException.class,()->carrier.options("OTHER",s));when(catalog.warehouses("OTHER")).thenReturn(Collections.emptyList());assertEquals(false,carrier.match("OTHER",row("mode","AUTO","items",Arrays.asList(row("id",s,"control_version",1))),"test").get(0).get("success"));db.update("UPDATE oms_order SET manual_hold=1");assertEquals(false,match(s,1,"MANUAL","A").get("success"));db.update("UPDATE oms_order SET manual_hold=0");db.update("UPDATE oms_platform_order SET change_pending=1");assertEquals(false,match(s,1,"MANUAL","A").get("success"));db.update("UPDATE oms_platform_order SET change_pending=0,fulfillment_block_reason='refund pending'");assertEquals(false,match(s,1,"MANUAL","A").get("success"));db.update("UPDATE oms_platform_order SET fulfillment_block_reason=''");db.update("UPDATE oms_order_shipment SET status='WAREHOUSE_PROCESSING'");assertEquals(false,match(s,1,"MANUAL","A").get("success"));assertEquals(1,number(document(s),"control_version"));}
    @Test void concurrentAdjustmentsHaveOneWinnerAndOneAudit() throws Exception {master("A",Arrays.asList(service("R1")),0,1);master("B",Arrays.asList(service("R1")),0,1);configure(0,1,Collections.emptyList(),"A","B");long s=shipment();java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(2);java.util.concurrent.CountDownLatch start=new java.util.concurrent.CountDownLatch(1);try{List<java.util.concurrent.Future<Boolean>> jobs=new ArrayList<>();for(int n=0;n<2;n++)jobs.add(pool.submit(()->{start.await();return Boolean.TRUE.equals(match(s,1,"MANUAL","B").get("success"));}));start.countDown();int winners=0;for(java.util.concurrent.Future<Boolean> job:jobs)if(job.get(10,java.util.concurrent.TimeUnit.SECONDS))winners++;assertEquals(1,winners);}finally{pool.shutdownNow();}assertEquals(2,number(document(s),"control_version"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_log WHERE action='CARRIER_ADJUST'",Integer.class));}
    @Test void catalogAndRulesRejectStaleChangesWithoutOverwriting(){master("A",Arrays.asList(service("R1")),0,1);assertThrows(IllegalArgumentException.class,()->master("A",Arrays.asList(service("R1")),0,0));configure(0,1,Collections.emptyList(),"A");assertThrows(IllegalArgumentException.class,()->configure(0,0,Collections.emptyList(),"A"));assertThrows(IllegalArgumentException.class,()->master("B",Arrays.asList(service("R9")),0,1));}
    @Test void fullOrderStageAndFiltersAdvanceOnlyAfterAllCarriersAreConfirmed(){mirror(Arrays.asList(receipt(1,10,"V1","R1")));long s=number(generate(0).get(0),"id");assertEquals("WAIT_CARRIER",summary().get("business_status"));assertEquals(1,business.list("VERIFY",null,"","","","","",0,1,20,"","","WAIT_CARRIER").getTotal());master("A",Arrays.asList(service("R1")),0,1);configure(0,1,Collections.emptyList(),"A");assertEquals(true,match(s,1,"AUTO","").get("success"));assertEquals("WAIT_DISPATCH",summary().get("business_status"));assertEquals(0,business.list("VERIFY",null,"","","","","",0,1,20,"","","WAIT_CARRIER").getTotal());assertEquals(1,business.list("VERIFY",null,"","","","","",0,1,20,"","","WAIT_DISPATCH").getTotal());}
    @Test void stoppedWarehouseAndOutboundQuantityBlockAdjustmentWithoutChangingSnapshot(){master("A",Arrays.asList(service("R1")),0,1);configure(0,1,Collections.emptyList(),"A");long s=shipment();Map<String,Object> before=document(s);when(catalog.warehouses("VERIFY")).thenReturn(Collections.emptyList());assertEquals(false,match(s,1,"MANUAL","A").get("success"));when(catalog.warehouses("VERIFY")).thenReturn(Arrays.asList(row("owner_code","O1","real_store_code","R1")));db.update("UPDATE oms_order_shipment_line SET shipped_quantity=1");assertEquals(false,match(s,1,"MANUAL","A").get("success"));assertEquals(before,document(s));}
    @Test void malformedBatchDoesNotPartiallyApplyAndHistoricalInactiveWarehouseCannotAutoMatch(){master("A",Arrays.asList(service("R1")),0,1);configure(0,0,Collections.emptyList(),"A");long s=shipment();Map<String,Object> before=document(s);assertThrows(IllegalArgumentException.class,()->carrier.match("VERIFY",row("mode","AUTO","items",Arrays.asList(row("id",s,"control_version",1),row("id",s,"control_version",1))),"test"));assertEquals(before,document(s));mirror(Arrays.asList(receipt(1,6,"V1","R1"),receipt(2,4,"V2","R2")));ReflectionTestUtils.setField(service,"catalog",catalog);when(catalog.warehouses("VERIFY")).thenReturn(Arrays.asList(row("owner_code","O1","real_store_code","R1")));assertThrows(IllegalArgumentException.class,()->generate(1));assertEquals(1,count());}
}
